// memoize(fn, { ttl, now }) caches results per argument list for ttl milliseconds
export function memoize(fn, { ttl = Infinity, now = Date.now } = {}) {
  const cache = new Map();
  const t = now();
  return (...args) => {
    const key = JSON.stringify(args);
    const hit = cache.get(key);
    if (hit && t - hit.at < ttl) return hit.value;
    const value = fn(...args);
    cache.set(key, { value, at: t });
    return value;
  };
}

