import { test } from 'node:test';
import assert from 'node:assert/strict';
import { memoize } from '../memo.js';
test('entries expire', () => {
  let clock = 0;
  let calls = 0;
  const f = memoize((x) => { calls++; return x * 2; }, { ttl: 100, now: () => clock });
  assert.equal(f(2), 4);
  clock = 50;
  assert.equal(f(2), 4);
  assert.equal(calls, 1);
  clock = 150;
  assert.equal(f(2), 4);
  assert.equal(calls, 2, 'recomputed after the ttl');
});

